export const allowedTypes=new Set(['food_pantry','food_bank','mobile_pantry','soup_kitchen','community_fridge']);
export const categories={food_pantry:'Groceries',food_bank:'Food banks',mobile_pantry:'Mobile pantry',soup_kitchen:'Hot meals',community_fridge:'Community fridge'};
export function miles(a,b){const r=Math.PI/180,q=Math.sin((b[0]-a[0])*r/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin((b[1]-a[1])*r/2)**2;return 3958.7613*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));}
export function normalize(data,center){if(!Array.isArray(data.resources))throw Error('The directory returned an unexpected response.');const seen=new Set();return data.resources.filter(r=>allowedTypes.has(r.resource_type)&&r.lat!=null&&r.lng!=null&&Number.isFinite(Number(r.lat))&&Number.isFinite(Number(r.lng))&&Math.abs(Number(r.lat))<=90&&Math.abs(Number(r.lng))<=180).map(r=>{const key=[String(r.name).toLowerCase().replace(/[^a-z0-9]/g,''),String(r.address).toLowerCase().replace(/avenue/g,'ave').replace(/street/g,'st').replace(/[^a-z0-9]/g,''),r.resource_type].join('|');return{...r,id:String(r.id),distance:miles(center,[Number(r.lat),Number(r.lng)]),key}}).filter(r=>{if(r.distance>5||seen.has(r.key))return false;seen.add(r.key);return true}).sort((a,b)=>a.distance-b.distance);}
export function filtered(rows,query,type,source){const q=query.trim().toLowerCase();return rows.filter(r=>(type==='All'||r.resource_type===type)&&(source==='All'||r.data_source===source)&&[r.name,r.address,r.city,r.state,r.zip,r.requirements_text].join(' ').toLowerCase().includes(q));}
export function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
export function hours(row){if(row.hours_status==='unknown')return 'Hours not confirmed. Call before traveling.';try{const h=typeof row.hours_json==='string'?JSON.parse(row.hours_json):row.hours_json;if(h&&typeof h==='object'){return Object.entries(h).filter(([k,v])=>typeof v==='string').map(([k,v])=>k+': '+v).join(' · ')||'Call to confirm hours.'}}catch{}return 'Call to confirm hours.';}
